begin transaction read only;
with wanted(name) as(values ('consume_rcap_screening_session'),('claim_pending_screening_result'),('record_rcap_screening_analytics_event'),('emit_rcap_screening_started_event')),
relations(name) as(values('public.consumer_pending_screening_results'),('public.participant_claim_events'),('public.rcap_screening_analytics_events'))
select jsonb_build_object(
'execution_context',jsonb_build_object('current_user',current_user,'session_user',session_user,'transaction_read_only',current_setting('transaction_read_only')),
'admission_analytics_trigger',(select jsonb_build_object('present',t.oid is not null,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid),'function_definition',pg_get_functiondef(t.tgfoid),'function_source_body_md5',md5(f.prosrc),'function_owner',pg_get_userbyid(f.proowner),'owner_insert',case when to_regclass('public.rcap_screening_analytics_events') is not null then has_table_privilege(pg_get_userbyid(f.proowner),to_regclass('public.rcap_screening_analytics_events'),'INSERT') else false end) from (select 1) one left join pg_trigger t on t.tgrelid=to_regclass('public.screening_sessions') and t.tgname='rcap_screening_started_event' and not t.tgisinternal left join pg_proc f on f.oid=t.tgfoid),
'functions',(select jsonb_agg(jsonb_build_object('name',w.name,'overloads',(select coalesce(jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'argument_names',p.proargnames,'input_argument_count',p.pronargs,'default_argument_count',p.pronargdefaults,'arguments',pg_get_function_arguments(p.oid),'result',pg_get_function_result(p.oid),'source_body_md5',md5(p.prosrc),'definition_md5',md5(pg_get_functiondef(p.oid)),'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'volatility',p.provolatile,'config',p.proconfig,'acl',p.proacl::text,'service_execute',has_function_privilege('service_role',p.oid,'EXECUTE'),'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE')) order by p.oid::regprocedure::text),'[]'::jsonb) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=w.name)) order by w.name) from wanted w),
'relations',(select jsonb_agg(jsonb_build_object('name',r.name,'present',c.oid is not null,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl::text,'anon_access',case when c.oid is not null then has_table_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,DELETE') end,'authenticated_access',case when c.oid is not null then has_table_privilege('authenticated',c.oid,'SELECT,INSERT,UPDATE,DELETE') end,'service_select',case when c.oid is not null then has_table_privilege('service_role',c.oid,'SELECT') end,'service_insert',case when c.oid is not null then has_table_privilege('service_role',c.oid,'INSERT') end,
'columns',(select coalesce(jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'acl',a.attacl::text) order by a.attnum),'[]'::jsonb) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
'constraints',(select coalesce(jsonb_agg(jsonb_build_object('name',co.conname,'definition',pg_get_constraintdef(co.oid)) order by co.conname),'[]'::jsonb) from pg_constraint co where co.conrelid=c.oid),
'indexes',(select coalesce(jsonb_agg(jsonb_build_object('name',ci.relname,'definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready) order by ci.relname),'[]'::jsonb) from pg_index i join pg_class ci on ci.oid=i.indexrelid where i.indrelid=c.oid),
'policies',(select coalesce(jsonb_agg(jsonb_build_object('name',p.polname,'command',p.polcmd,'roles',p.polroles,'role_names',(select jsonb_agg(r.rolname order by r.rolname) from pg_roles r where r.oid=any(p.polroles)),'using',pg_get_expr(p.polqual,p.polrelid),'with_check',pg_get_expr(p.polwithcheck,p.polrelid)) order by p.polname),'[]'::jsonb) from pg_policy p where p.polrelid=c.oid),
 'triggers',(select coalesce(jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid),'function_definition',pg_get_functiondef(t.tgfoid),'function_body_md5',(select md5(p.prosrc) from pg_proc p where p.oid=t.tgfoid),'function_md5',md5(pg_get_functiondef(t.tgfoid))) order by t.tgname),'[]'::jsonb) from pg_trigger t where t.tgrelid=c.oid and not t.tgisinternal)) order by r.name) from relations r left join pg_class c on c.oid=to_regclass(r.name))
) as clinic_supplemental_contract;
commit;
